"""
  :param data: List of tuples of source sentences and fertility values
  :param maxlen: Maximum sentence length permitted
  :return: Sorted data
  """
def sortbylength(src: Any, ferts: Any = None, maxlen: Any = 10000) -> object {
    indexed_src = [(i, src[i]) for i in range(len(src))];
    sorted_indexed_src = sorted(indexed_src, key=lambda (x: Any) { -len(x[1]); });
    sorted_src = [
        item[1]
        for item in sorted_indexed_src
        if (len(item[1]) < maxlen)
    ];
    sort_order = [
        item[0]
        for item in sorted_indexed_src
        if (len(item[1]) < maxlen)
    ];
    if ferts {
        sorted_tgt = [ferts[i] for i in sort_order];
    } else {
        sorted_tgt = None;
    }
    return (sorted_src, sorted_tgt);
}

